// Crisp HUD text: drawn on a 2D overlay at device resolution with real fonts, so it never inherits the WebGPU canvas's
// render scale. Panels, rings, the map and markers stay on the GPU. Without a 2D context (tests, odd browsers) the SDF glyphs remain.
let hud2d30=null,hudScale30=1;const textWidths30=new Map();
function initHud2d30(){try{const c=document.createElement('canvas');c.id='hud2d';c.setAttribute('aria-hidden','true');document.body.appendChild(c);hud2d30=c.getContext('2d');document.fonts?.addEventListener?.('loadingdone',()=>textWidths30.clear());}catch(e){hud2d30=null;}}
function sizeHud2d30(){const c=hud2d30.canvas,dpr=Math.min(2,window.devicePixelRatio||1),w=Math.max(1,Math.round((c.clientWidth||innerWidth)*dpr)),h=Math.max(1,Math.round((c.clientHeight||innerHeight)*dpr));
 if(c.width!==w||c.height!==h){c.width=w;c.height=h;textWidths30.clear();}hudScale30=w/Math.max(1,width);hud2d30.clearRect(0,0,w,h);}
function fontFor30(px){const display=px>=24*clamp9(height/900,.72,1.15);return display?Math.round(px*hudScale30*1.08)+'px Bangers,Impact,"Arial Black",sans-serif':'700 '+Math.round(px*hudScale30*.94)+'px Rubik,"Segoe UI",system-ui,sans-serif';}
function text(str,x,y,px=17,col=[.89,.94,.93,1]){
 if(hud2d30){const ctx=hud2d30,s=hudScale30,a=col[3]??1;str=String(str);ctx.font=fontFor30(px);ctx.textBaseline='middle';ctx.lineJoin='round';
  ctx.lineWidth=Math.max(2,px*s*.16);ctx.strokeStyle='rgba(3,9,12,'+(.88*a)+')';ctx.strokeText(str,x*s,(y+px*.75)*s);
  ctx.fillStyle='rgba('+Math.round(col[0]*255)+','+Math.round(col[1]*255)+','+Math.round(col[2]*255)+','+a+')';ctx.fillText(str,x*s,(y+px*.75)*s);return;}
